const headings = ['Name the decision','Describe the starting material','Set the safe first move','Make evidence visible','Separate routine from exception','Design the review moment','Write the cross-time-zone handoff','Check the permission boundary','Learn from correction','Close with the owner action'];

function paragraph(s: Spec, i: number): string {
  const starts = [
    `For ${s.focus}, begin with the decision the owner needs to make rather than with a broad request to “help.” ${s.audience} needs ${s.result}. Write that outcome in one sentence, then list what will count as ready for review. The description should be concrete enough that an assistant can prepare the work and a second person can inspect it without guessing. ${s.lens} matters because a queue can look busy while still hiding the actual choice.`,
    `The starting material for ${s.focus} is ${s.object}. Record where it came from, when it was last checked, and which parts are missing. Then apply the first move: ${s.first}. A brief that names the input prevents the assistant from searching every connected tool or treating an old message as current authority. It also gives the owner a fair way to distinguish incomplete input from incomplete work.`,
    `The first safe move should be small enough to reverse. In this case, it means ${s.first}. Give the assistant one ordinary example and one example that must stop. The point is not to script every sentence; it is to show the boundary between preparation and decision. A Philippines-based assistant can work independently inside a defined lane when the lane includes its trigger, source, expected record, and next reviewer.`,
    `Make the evidence visible beside the work. For ${s.focus}, preserve the request, relevant source, action taken, unresolved question, and current state. Do not make the reviewer infer why an item was changed. If a fact is unavailable, label it unavailable. If a statement is an interpretation, label it as a proposed reading. This protects customer-facing copy, internal reporting, and future handoffs from a confident sentence that has no traceable basis.`,
    `Routine work ends when it reaches the agreed result; the exception begins when the request changes its consequence. The important exception here is ${s.failure}. When it appears, pause the consequential step, retain the surrounding context, and ask the named owner a narrow question. The assistant may suggest safe preparation, but it should not convert urgency, repetition, or a missing reply into authority.`,
    `Review should happen at the point where a mistake would become expensive or public. Inspect a representative sample for completeness, source handling, status accuracy, and boundary judgment. For ${s.focus}, ask whether another reviewer could tell what happened and what decision remains. Correct the record itself when necessary, then correct the brief if the same ambiguity could return. A review is useful when it improves the next item, not when it merely assigns blame.`,
    `A time-zone gap makes the handoff part of the work. End the shift with completed items, items waiting on evidence, blocked items, and one explicit next owner. Mention the relevant date, local time, and source record when timing matters. Avoid “please review” as a standalone instruction; state the choice needed. The next person should be able to continue ${s.focus} without opening scattered chats or assuming that silence means approval.`,
    `Tools should follow the role rather than define it. Map each action as view, draft, edit, send, approve, or delete. Grant only what is needed for the current lane, use individual accounts where possible, and retain owner control over irreversible changes. The boundary here is ${s.boundary}. If the role expands, review the new access, training, and approval path together instead of adding a permission as a quick fix.`,
    `After several cycles, review the correction pattern. Was the source unclear, the example incomplete, the status vocabulary inconsistent, or the owner unavailable? Store the answer in ${s.object} or the role brief, and note who approved the change. This is especially important for outsourced support: the assistant should not be judged against a private rule that was never written, while the owner should not have to repeat the same correction forever.`,
    `The owner action is to test one real but bounded item, inspect the evidence, confirm the stop condition, and decide whether the lane is ready for more volume. Do not treat this method as a guarantee or as legal, tax, financial, employment, medical, or security advice. For ${s.focus}, the durable outcome is a clearer handoff: useful preparation from the assistant, visible uncertainty, and consequential judgment retained by the authorized owner.`
  ];
  return starts[i];
}

const repairNotes: Record<string, string> = {
  'outsourced-assistant-weekly-capacity-map': `A useful capacity map also records what is deliberately not scheduled. For each recurring duty, note the assumed frequency, the effort range, the input that must arrive first, and the person who can change the priority. A Philippines-based assistant can prepare this inventory and flag collisions, but should not resolve a collision by silently dropping a committed item. The owner can choose to defer, delegate, shorten, or remove work, and that choice belongs in the Monday planning note. Keep a small reserve for questions and corrections; treating every minute as committed makes the map look precise while hiding normal operating variance. When a new request arrives, compare it with the map, record the conflict, and state the decision needed. This turns capacity into a shared fact rather than a personal judgement about an outsourced assistant. Recheck the map after one week and revise the effort assumptions from observed evidence, not optimism. Add a decision column for work that is committed, flexible, waiting, or outside the current lane. That small vocabulary helps the owner see why an item is present and what can move without creating a hidden promise. The assistant can estimate effort from prior approved examples and mark uncertainty, but the estimate is not a deadline. If the estimate changes, preserve the original assumption and explain whether the input, scope, or dependency changed. A weekly review should examine unfinished work without treating every delay as an individual failure. Ask which missing source, approval, or handoff caused the item to wait, then improve that part of the routine. The next capacity map should carry one concrete correction forward so the plan becomes more accurate through inspection. For this route, also separate a recurring obligation from a one-time request. Record whether each row consumes a fixed appointment, a flexible work block, or attention that cannot be predicted. This distinction helps an owner decide what to move when a new request is genuinely urgent. The assistant may prepare two or three capacity scenarios, but every scenario should show its assumptions and the work displaced. The owner selects the scenario and records the tradeoff. A useful Friday review compares planned and actual effort without turning the difference into a performance verdict. Ask whether the estimate was wrong, the input arrived late, the scope expanded, or an approval waited. Carry that explanation into the next Monday note. The map is valuable when it makes a choice visible before the assistant is asked to promise a date.`,
  'filipino-virtual-assistant-escalation-ladder': `An escalation ladder works when it gives the assistant enough structure to ask a smaller question. The card should capture the request, relevant account or record, known facts, uncertainty, possible impact, urgency, and the decision that only the reviewer can make. Separate routine clarification from a policy exception, payment issue, customer complaint, or access concern. A Filipino virtual assistant may gather the approved context and draft the question; the ladder must not turn a quiet reviewer into implied approval. Set a response window and a backup path, then state what happens when both are unavailable: preserve the record, pause the consequential action, and notify the owner through the approved channel. Review a sample of escalations for missing context and unnecessary escalation. If the same question repeats, improve the card or source instruction. The measure of a good ladder is not fewer questions; it is better-scoped questions that preserve authority and make the next decision easier. Give each rung a clear entry test and an exit test. For example, a routine question may return to the assistant when the approved source answers it, while an exception remains with the named owner until a written decision is recorded. Do not create a ladder with impressive labels but no usable response path. Include the approved channel, backup reviewer, expected evidence, and the action that remains paused. A remote assistant should be able to prepare a concise escalation without copying an entire conversation or exposing unrelated customer information. The reviewer should answer the decision asked, state any new boundary, and identify whether the card needs updating. This makes escalation a learning loop: the assistant gets better context, the owner sees recurring ambiguity, and the routine gains a durable rule without pretending that silence is consent. Add a severity test that describes consequence rather than emotion. A calm request can still require an owner because it changes a policy or commitment, while an urgent message may remain routine if an approved answer exists. Include the timestamp, time zone, and next review point so the receiving person can act without reconstructing the shift. The assistant should state what has not been done, not merely what has been collected. If the first reviewer declines the item, preserve that response and route only the unresolved decision to the backup. This avoids duplicate chasing and keeps the Filipino virtual assistant’s preparation lane distinct from approval. Revisit the ladder after a real exception and change one field at a time so the team can understand the new rule.`,
  'outsourced-assistant-knowledge-base-review': `Review the knowledge base by following real assistant questions from intake to answer. Record the exact question, the source document, its owner, its last review date, the answer supported by that source, and any conflict with another instruction. A short register is more useful than a large collection of pages that no one can distinguish. The outsourced assistant can identify duplicates, mark stale material, and draft a proposed replacement, but the policy owner approves the meaning of a corrected answer. Do not reward speed when the source is contradictory. A safe response is to preserve the question, explain that the answer is under review, and escalate the decision. Check whether permissions, links, examples, and escalation contacts still match the current lane. Review a new sample after the register changes and retire only material that has an identified replacement or an explicit owner decision. This makes consistency a property of the source system, not a demand that a Filipino assistant remember every informal instruction. Add a review owner and a next-review date to every instruction that can change an assistant’s answer. If the owner is unknown, the assistant may record the gap and route it for assignment, but should not treat an old document as approved merely because it is easy to find. Compare the language in the source with the action the assistant is expected to take. A policy sentence that sounds clear may still omit the customer type, exception, required evidence, or stop condition. Keep examples beside the rule and label them as examples so a hypothetical case is not mistaken for a new policy. When two sources conflict, preserve both titles and dates in the register, state the exact difference, and ask which one governs. After a correction, test the same question again and note whether the answer is now reproducible. The goal is a knowledge base that supports careful outsourced assistant work while keeping policy meaning with its accountable owner. Add a provenance field for each answer: source title, section, owner, checked date, and permitted audience. This makes it possible to distinguish a customer-facing instruction from an internal note or a draft suggestion. The assistant can perform the comparison and report missing fields, but should not decide that a newer-looking document automatically wins. When a source is retired, record its replacement and the reason for retirement so old links do not quietly return through search. Sample questions from ordinary queues, exceptions, and handoffs because a knowledge base can appear accurate while failing only at the edge cases. Test the revised answer with a second reader who did not write the source. If that reader asks the same clarification, improve the instruction or route the ambiguity to the policy owner. A clean register supports consistent delegated work without turning a Filipino assistant into the owner of policy meaning.`,
  'remote-assistant-shift-handoff': `A remote shift handoff should be written for someone who was not present. Name the route or queue, the last completed action, the exact evidence location, the next safe action, and the point at which work must stop. Use an absolute date and time with a stated time zone when a deadline matters. An outsourced assistant can prepare the note, reconcile statuses, and identify a missing reply; the next person still needs the authority to approve a customer-facing or irreversible action. Keep waiting, blocked, drafted, approved, and complete as separate states. A sentence such as “all good” hides the difference between no issue and no review. The owner should sample handoffs for recoverability: could another assistant continue without reopening private chat history? If not, update the handoff template or SOP. A good remote routine respects the Filipino assistant’s working context while keeping decisions with the named owner, regardless of who happens to be online. Include a compact summary at the top, then preserve the detail needed to verify it. The summary should identify what changed during the shift, what is still waiting, and the one decision that would unlock the next safe action. Do not use the handoff to assign blame or to hide an uncertain status behind a cheerful phrase. If a message is unanswered, name the channel, last attempt, and next permitted follow-up time. If a task is ready for review, link the exact draft or record and say what the reviewer must inspect. An assistant working across the Philippines and another time zone can make this practical by writing dates, zones, and ownership explicitly. The next shift should be able to resume from the evidence trail, not from memory or a private conversation. Review recurring handoff gaps weekly and update the template when the same missing field appears twice. A complete note also distinguishes the person who performed the last action from the person who may authorize the next one. Include links that the next shift can open, but do not copy sensitive material into a broad channel merely for convenience. If a task is blocked by a missing reply, write the last request, the permitted follow-up time, and the escalation owner. If it is ready, state the exact review question. Across Philippines and owner time zones, write both the calendar date and local clock time because a weekday alone can cross midnight. A handoff should survive a normal shift change, not depend on the original assistant remembering an unwritten promise.`,
  'outsourced-assistant-approval-queue': `An approval queue is a decision boundary, not just a list of tasks. Each item should show what is being requested, the source evidence, the proposed action, the consequence of waiting, the person who may approve it, and the required response format. An outsourced assistant can assemble a complete packet, check that required fields are present, and return an item for missing context. It should not move an item to approved because a deadline is close or because the owner has approved a similar item before. Use separate statuses for ready for review, changes requested, approved, rejected, and expired. Keep the original request attached when the draft changes so the reviewer can see what was altered. Sample the queue for stale approvals and duplicate records, then improve the intake rule that caused them. This gives a Filipino virtual assistant a clear preparation lane while protecting the owner’s responsibility for money, policy, customer promises, or public claims. Add a reviewer decision field that records approved, rejected, returned, or approved with a stated condition. A blank field means the item is still waiting, even when the task has been discussed in chat. The assistant can check that the packet contains the source, affected record, proposed wording, and consequence of delay. It can also group similar requests for easier review, but grouping must not merge their evidence or make one approval appear to cover another. When the owner requests changes, preserve the previous draft and explain the difference in the new packet. This protects the queue from silent edits and gives the next reviewer a reliable history. Sample both old and newly submitted items for stale evidence, duplicate requests, unclear ownership, and accidental customer promises. If the queue repeatedly receives incomplete packets, improve the intake form or checklist instead of expecting the assistant to guess what the reviewer meant. Add an explicit expiration rule so a stale approval cannot be mistaken for current permission. The assistant can sort by age, impact, missing evidence, and named reviewer, then prepare a concise daily view. It should never reorder an item to make a waiting decision look complete. When a packet changes, preserve both the prior wording and the requested revision, with the reason for return. The owner can approve, reject, defer, or ask for more evidence; each result should be recorded in the queue. A Filipino virtual assistant can make this structure easy to inspect while leaving financial, policy, customer, and public-claim consequences with the authorized decision-maker. Review a small sample of closed items to see whether the recorded decision matches the action later taken.`,
  'filipino-assistant-data-cleanup-scope': `Data cleanup needs a written definition of what may change and what must remain untouched. Start with a field map that names the source, allowed format, duplicate rule, missing-value treatment, and review owner. A Filipino assistant may normalize an approved spelling, flag a likely duplicate, or prepare a change list. Deletion, merging, history changes, and edits to fields used for forecasts or commitments require an explicit decision. Preserve the before value and reason for every non-trivial change, even when the system provides an audit log. Test a small sample against the source record before expanding the lane. If two records disagree, do not choose the more convenient value; retain both evidence points and escalate the ambiguity. The owner can then decide whether to correct, defer, or leave the record unchanged. Review the cleanup by accuracy, traceability, and escalation judgment, not by the number of rows touched. A bounded scope protects both reporting and the outsourced assistant from invisible assumptions. Define the sample before editing the wider set: identify which records are included, which fields are in scope, and which source wins when the values differ. The assistant should keep a proposed change list separate from the live update until the owner or designated reviewer accepts the rule. For every ambiguous row, record the competing values, their sources, and the question that would resolve the conflict. Do not use a likely duplicate as permission to merge people, organizations, or history. A Filipino assistant can make the evidence easier to inspect by grouping similar cases and highlighting fields that need a decision. The review should include a before-and-after sample, the reason for each accepted rule, and a count of records left unchanged because evidence was insufficient. That last category is important: restraint is a valid outcome when the source is unclear. Revisit the scope after the first small batch and change the rule only with a named owner decision. Add a change ledger with record identifier, field, old value, proposed value, source, rule applied, reviewer, and decision date. Keep the proposed ledger separate from the live system until the sample is accepted. This lets an outsourced assistant demonstrate careful preparation without making a silent bulk edit. If a field has multiple possible formats, choose one only when the owner has documented the rule; otherwise preserve the value and flag it. For duplicate candidates, show the matching evidence and the missing evidence rather than assigning confidence as if it were approval. Review excluded rows as deliberately untouched work. That list can reveal a source problem, but it can also prove that the assistant respected the boundary. After the owner approves a rule, update the scope document so the next Filipino assistant does not have to infer it from past changes.`,
  'outsourced-assistant-research-brief': `A research brief becomes useful when every material statement has a visible path back to evidence and a stated limit. Begin with the decision question, population or subject, date range, source type, and interpretation the owner needs. An outsourced assistant can discover sources, record passages, compare definitions, and draft open questions. The owner decides whether the evidence is sufficient for a public claim, a policy change, or another consequential use. Keep search leads separate from sources that actually support a conclusion. For each source, note why it is relevant, what it cannot establish, and whether its data or guidance is current enough for this question. If sources disagree, describe the disagreement instead of smoothing it into a confident sentence. The brief should end with a recommended next review, not a manufactured certainty. A Filipino assistant working on research can make the evidence easier to inspect while the accountable reviewer retains interpretation, publication, and risk decisions. Add a source table with the question each source can answer, the question it cannot answer, the date checked, and the reason it belongs in the brief. This prevents a search result or attractive summary from carrying more weight than the underlying evidence. Keep direct observations, source claims, and the assistant’s proposed interpretation in separate fields. If a source uses a different definition, explain the mismatch before comparing it with another source. A useful brief also records what would change the working conclusion, such as a newer rule, a different population, or an owner decision about scope. The assistant can prepare that uncertainty register and highlight gaps, but should not turn missing evidence into a confident recommendation. Before publication or policy use, the accountable reviewer should inspect the material claims, source links, dates, and limitations. The closing action is deliberately modest: select one open question for further checking and record who will decide whether the evidence is sufficient. Add a claim register with the sentence proposed, supporting source, relevant passage, population, date checked, and limitation. A link alone does not show that the source supports the exact wording. The assistant can compare definitions and identify where a source stops, then draft a narrower sentence that stays inside the evidence. The reviewer decides whether that sentence belongs in public copy. Keep source discovery, source reading, interpretation, and recommendation as separate stages. If a source is inaccessible or its method is unclear, mark the gap rather than substituting a more convenient source. A Philippines-based research assistant can make a brief decision-ready by surfacing disagreement, but cannot resolve disagreement by choosing the most persuasive paragraph. Close with a bounded conclusion and one question for further checking.`,
  'outsourced-assistant-meeting-prep-packet': `A meeting-prep packet should help the owner decide what deserves time before the call begins. Include the purpose, participants, relevant prior decisions, open questions, documents, proposed agenda, and the decision or input requested from each attendee. An outsourced assistant can gather approved materials, check links, draft neutral questions, and identify missing context. It should not invent a participant position, promise an outcome, or circulate sensitive material beyond the approved list. Mark facts, assumptions, and proposed discussion points separately. If a preparation source is stale or contradictory, flag it beside the affected agenda item and ask the owner which version governs. After the meeting, connect the packet to the approved notes and action queue so the preparation does not become an orphaned document. Review whether the packet reduced searching and exposed the real decision. This gives a Filipino assistant a concrete administrative lane while leaving prioritization, commitments, and sensitive judgement with the owner. Organize the packet around decisions rather than around a pile of links. For each agenda item, state the background, the question, the evidence to read, the person who owns the decision, and the output expected from the meeting. Separate confirmed facts from assumptions so the owner can correct the packet quickly. If participants work across time zones, include the meeting date, local time, duration, and preparation deadline in the handoff. The assistant may identify that a document is missing or that two notes disagree, then ask which source should govern. It should not fill the gap by predicting what a participant believes or by circulating material that has not been approved for the group. After the meeting, compare the final notes with the packet and mark which questions were answered, deferred, or changed. That comparison improves the next preparation cycle and keeps the outsourced assistant’s role focused on evidence, organization, and safe follow-through. Add a one-page decision index at the top: item, owner, requested input, evidence link, preparation status, and unresolved question. This keeps the owner from mistaking a long reading list for readiness. For a cross-time-zone meeting, state the meeting date, each relevant local time, and the preparation cutoff in one place. The assistant can check that links work and that the approved attendees receive the right packet, but should not infer that an absent person agrees. After the call, mark each item answered, deferred, changed, or still open and link the approved note. That comparison gives the next outsourced assistant a reliable starting point and shows whether preparation exposed the actual decision.`,
  'outsourced-assistant-vendor-follow-up': `Vendor follow-up should distinguish a status request from a change to an obligation. The assistant can verify the known contact, quote the existing request, ask for a delivery update, record the response, and prepare an escalation when the supplier misses an agreed checkpoint. It should not accept a substitute, revised price, changed payment term, or new delivery promise unless the owner has explicitly granted that authority. Keep the original commitment, supplier reply, proposed change, evidence link, and decision needed together. If a message arrives from an unfamiliar address or asks for sensitive information, verify it through a known channel before replying. A Philippines-based operations assistant can keep the queue current and make unanswered requests visible without becoming the commercial decision-maker. Review a sample for accurate status wording, correct contact handling, and clean escalation. When the same vendor question returns, update the record or follow-up script with the smallest durable clarification. Separate the supplier’s factual update from any proposed change to the relationship. A useful follow-up note can say that a delivery is still unconfirmed, that a contact asked a new question, or that evidence is missing; it should not imply acceptance of a revised obligation. Keep the known contact method in the record and verify unexpected requests through an independent channel before sharing sensitive information. The assistant may draft a concise message that repeats the existing request, asks for the missing status, and gives the agreed checkpoint. If the supplier proposes a substitute, new term, or different destination, preserve the proposal and route it to the owner. Review whether the reply accurately describes what is known, what is only proposed, and what decision remains. This gives an outsourced assistant a productive queue-management lane while protecting the business from accidental commitments made during routine chasing. Keep four fields separate in every vendor record: original request, supplier response, proposed change, and owner decision. A status phrase such as “on track” should be tied to the supplier’s wording or to a dated evidence record, not to an assumption. Verify an unexpected sender through the known contact path before sharing account or operational details. The assistant can ask whether an existing checkpoint remains valid and can prepare the escalation when it does not. If a substitute or new term appears, preserve it verbatim enough for the owner to understand the proposal, then stop. A Filipino or Philippines-based assistant can keep follow-up timely across time zones by recording the last contact and next permitted attempt. Review closed items for accidental commitments, unclear status language, and missing evidence. Improve the script only after the owner confirms the boundary.`,
  'outsourced-assistant-quality-sample-plan': `A quality sample plan should tell the reviewer what to inspect and why the sample represents the lane. Define the work population, selection rule, review frequency, criteria, severity levels, and action for a failed sample. An outsourced assistant should see the criteria before work begins; changing the standard after a return makes coaching arbitrary. Score accuracy, completeness, source use, tone, timeliness, and escalation judgment only where each criterion is relevant. Preserve a short note explaining the evidence behind each score and separate a process defect from a one-off mistake. A Filipino assistant can help collect samples and record corrections, while the owner decides whether the SOP, training, access, or scope needs to change. Do not use a score as a hidden proxy for personality or availability. Recheck the plan after several samples: if reviewers disagree, clarify the example or scoring rule. The goal is a fair, inspectable feedback loop that improves delegated work without inventing a performance claim. Explain why the selected sample represents the work, including whether it covers different request types, shifts, channels, or exception paths. The reviewer should record the evidence for each finding and distinguish a missing source, a transcription error, an unclear instruction, and a boundary violation. Those causes need different corrections. A Filipino assistant should be able to read the rubric before completing the work and understand which cases must be escalated instead of scored as ordinary errors. Keep examples of acceptable, return-for-edit, and stop-and-escalate work beside the criteria. When reviewers disagree, compare their readings with the example and revise the rule only after an owner decision. Do not turn a single sample into a sweeping claim about quality. Use the findings to improve the SOP, training note, or access boundary, then select a later sample to see whether the correction is understandable. This keeps review focused on the delegated routine and makes feedback fair, specific, and actionable. Define the population before selecting a sample: include ordinary requests, exceptions, different channels, and handoffs when those variations belong to the lane. Record why each item was chosen so the reviewer can tell a useful sample from a convenient one. Score only observable work against criteria the assistant saw in advance. If a failure comes from an unclear instruction, repair the instruction rather than treating it as a personal defect. A Filipino assistant can collect examples and explain the evidence, while the owner decides whether training, access, scope, or the SOP needs revision. Re-sample after the correction and compare the same failure type. Never turn a small sample into a claim about a person or a business result.`,
  'filipino-virtual-assistant-calendar-timezone-rules': `Calendar rules should store a canonical time zone, the displayed local time, the participant’s confirmed zone, and the conversion used for the invitation. Never rely on “tomorrow morning” when a distributed team is involved. A Filipino virtual assistant can compare availability, draft options, check daylight-saving implications where relevant, and send a confirmation only within the approved lane. Moving a high-stakes meeting, changing a customer commitment, or overriding an owner’s protected time requires approval. Put the date, time, zone, duration, location or link, and preparation requirement in the confirmation format. When a participant gives an ambiguous time, preserve the message and ask for the zone rather than guessing. Review a sample of bookings for conversion accuracy and for whether the written record would let another assistant reconstruct the decision. A clear calendar routine reduces avoidable confusion while keeping priority and commitment decisions with the owner. Use one canonical zone for the owner’s schedule, then show each participant’s local display beside it instead of hiding the conversion. Record the date as well as the weekday because a distributed team may cross midnight. If daylight-saving rules could affect the meeting, verify the relevant zone and show the converted result in the confirmation rather than assuming that a familiar offset remains constant. The assistant can offer options that fit the approved availability, but cannot move protected time or create a customer promise without approval. When a participant replies with an ambiguous phrase, preserve the original message and ask a focused question: which date, which zone, and how long should the meeting be? After booking, inspect the invitation, link, attendees, duration, and preparation note as one packet. A later assistant should be able to reconstruct why that time was chosen and who approved an exception. Review a small sample for conversion mistakes and unclear ownership, then correct the calendar rule or confirmation format so the same confusion does not recur. Add a confirmation record containing the canonical zone, participant zones, date, local display, duration, link, and approval for any exception. The weekday is useful for readability but cannot replace the date. If daylight-saving rules apply, record the zone name and the conversion checked rather than relying on a remembered offset. A Filipino virtual assistant can compare approved availability and present options, but the owner retains protected-time and customer-commitment decisions. When a participant says “next morning,” ask for date and zone and preserve the clarification. After booking, inspect the invitation as a second reader would: can another assistant explain why this time was chosen? Review a sample across time-zone boundaries and correct the confirmation format when a recurring ambiguity appears.`,
};

function makePost(s: Spec, index: number): BlogPost {
  return { slug: s.slug, title: s.title, published: '2026-08-21', minutes: 11,
    excerpt: `A practical OutsourcingAssistant.com guide for ${s.audience}: make ${s.focus} reviewable, useful, and bounded.`,
    takeaway: `${s.result}. Start with ${s.first}, and keep ${s.boundary} with the owner.`,
    image: { url: `/images/blog-2026-08-21/${s.slug}.png`, alt: s.title },
    sections: [...headings.map((heading, i) => ({ heading, body: paragraph(s, (i + index) % 10) })), { heading: 'Route-local operating guidance', body: `${s.evidence}\n\n${repairNotes[s.slug] ?? ''}` }],
    faqs: [
      { q: `What should the owner define before delegating ${s.focus}?`, a: `Define the input, finished result, source of truth, review point, and the action that remains with the owner: ${s.boundary}.` },
      { q: 'What should happen when the normal path breaks?', a: `Pause the consequential step, keep the relevant evidence, and route a concise question to the named reviewer. Do not guess because the request is urgent.` },
      { q: 'How can a distributed team improve the routine?', a: 'Review a small representative sample, record corrections, and update the brief or example when the same ambiguity returns.' }
    ],
    internalLinks: [{ href: '/resources/assistant-sop-handoff-checklist', label: 'Use the assistant SOP handoff checklist' }, { href: '/services', label: 'Review staffing and support services' }]
  };
}

export const dailyBlogBatch20260821: BlogPost[] = specs.map(makePost);
